insert into categories (name, slug, description, sort) select 'Earrings', 'earrings', 'Hoops, jhumkas, dangles and studs, handcrafted in oxidised brass and German silver.', 0 where not exists (select 1 from categories where parent_id is null and slug = 'earrings');
insert into categories (parent_id, name, slug, description, sort) select (select id from categories where parent_id is null and slug = 'earrings'), 'Hoops', 'hoops', 'Clean circles and sculpted loops, from everyday minis to statement hoops.', 0 on conflict (parent_id, slug) do nothing;
